package com.thangit.boardinghouse.service;

import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.dto.request.accountant.AccountantRequests.*;
import com.thangit.boardinghouse.repository.*;
import com.thangit.boardinghouse.security.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Scoped projections of existing source documents, never a second money ledger. */
@Service
public class FinanceWorkspaceService {
 private final JdbcClient db;private final ManagementFinanceService finance;
 public FinanceWorkspaceService(JdbcClient db,ManagementFinanceService finance){this.db=db;this.finance=finance;}
 public record Filter(Long propertyId,LocalDate startDate,LocalDate endDate,String tab,String keyword,String status,String category,String method,int page,int size,Long organizationId,Long areaId){public Filter(Long propertyId,LocalDate startDate,LocalDate endDate,String tab,String keyword,String status,String category,String method,int page,int size){this(propertyId,startDate,endDate,tab,keyword,status,category,method,page,size,null,null);}}
 private void validate(Filter f){if(f.startDate()==null||f.endDate()==null||f.endDate().isBefore(f.startDate())||f.endDate().isAfter(f.startDate().plusYears(2))||f.page()<0||f.size()<1||f.size()>100)throw fail("FINANCE_FILTER_INVALID");}
 @Transactional(readOnly=true) public Map<String,Object> workspace(AuthenticatedUser actor,Filter f){
  validate(f);var ids=finance.scope(actor,f.propertyId());
  if(f.organizationId()!=null||f.areaId()!=null){var groupArgs=new HashMap<String,Object>();groupArgs.put("ids",ids.isEmpty()?List.of(-1L):ids);String group="";if(f.organizationId()!=null){group+=" AND organization_id=:organization";groupArgs.put("organization",f.organizationId());}if(f.areaId()!=null){group+=" AND area_id=:area";groupArgs.put("area",f.areaId());}ids=db.sql("SELECT property_id FROM organization_property_relationships WHERE property_id IN (:ids) AND ended_at IS NULL"+group).params(groupArgs).query(Long.class).list();}
  var safe=ids.isEmpty()?List.of(-1L):ids;
  var args=new HashMap<String,Object>();args.put("ids",safe);args.put("start",f.startDate());args.put("until",f.endDate().plusDays(1));
  var result=new LinkedHashMap<String,Object>();result.put("propertyIds",ids);result.put("startDate",f.startDate());result.put("endDate",f.endDate());result.put("summary",new ManagementFinanceRepository(db).summary(ids,f.startDate(),f.endDate()));result.put("trend",new ManagementFinanceRepository(db).trend(ids,f.startDate(),f.endDate()));
  result.put("properties",db.sql("SELECT p.id,p.name,r.organization_id organizationId,r.area_id areaId,o.name organizationName,a.name areaName FROM properties p LEFT JOIN organization_property_relationships r ON r.property_id=p.id AND r.ended_at IS NULL LEFT JOIN organizations o ON o.id=r.organization_id LEFT JOIN management_areas a ON a.id=r.area_id WHERE p.id IN (:ids) ORDER BY p.name").param("ids",finance.scope(actor,null).isEmpty()?List.of(-1L):finance.scope(actor,null)).query().listOfRows());
  result.put("ledgerBasis","RECORDED_VALID_SOURCE_EVENTS_UNVERIFIED_OPENING");result.put("bankIntegration",false);
  String method="cashbook".equals(f.tab())?"CASH":"bankbook".equals(f.tab())?"BANK_TRANSFER":blank(f.method());
  var openingArgs=new HashMap<>(args);String methodSql=method==null?"":" AND method=:method";if(method!=null){args.put("method",method);openingArgs.put("method",method);}
  BigDecimal opening=db.sql("SELECT COALESCE(SUM(cash_in-cash_out),0) FROM management_cash_events WHERE property_id IN (:ids) AND occurred_at<:start"+methodSql).params(openingArgs).query(BigDecimal.class).single();
  var totals=db.sql("SELECT COALESCE(SUM(cash_in),0) incoming,COALESCE(SUM(cash_out),0) outgoing FROM management_cash_events WHERE property_id IN (:ids) AND occurred_at>=:start AND occurred_at<:until"+methodSql).params(args).query().singleRow();
  result.put("ledger",Map.of("opening",opening,"incoming",totals.get("incoming"),"outgoing",totals.get("outgoing"),"closing",opening.add(money(totals.get("incoming"))).subtract(money(totals.get("outgoing"))),"verified",false));
  result.put("funds",db.sql("SELECT method,COALESCE(SUM(CASE WHEN occurred_at<:start THEN cash_in-cash_out ELSE 0 END),0) opening,COALESCE(SUM(cash_in-cash_out),0) closing FROM management_cash_events WHERE property_id IN (:ids) AND occurred_at<:until AND method IN ('CASH','BANK_TRANSFER') GROUP BY method").params(args).query().listOfRows());
  result.put("costCategories",db.sql("SELECT category,COALESCE(SUM(amount),0) amount FROM management_expense_events WHERE property_id IN (:ids) AND occurred_on>=:start AND occurred_on<:until GROUP BY category").params(args).query().listOfRows());
  result.put("byProperty",db.sql("SELECT p.id,p.name,COALESCE(SUM(e.cash_in),0) incoming,COALESCE(SUM(e.cash_out),0) outgoing FROM properties p LEFT JOIN management_cash_events e ON e.property_id=p.id AND e.occurred_at>=:start AND e.occurred_at<:until WHERE p.id IN (:ids) GROUP BY p.id,p.name").params(args).query().listOfRows());
  String source=switch(Objects.toString(f.tab(),"overview")){
   case "deposits" -> "SELECT d.id,d.property_id,d.required_amount,d.balance_amount,d.reconciliation_status status,NULL event_date,COALESCE(c.code,b.code,CONCAT('COC-',d.id)) code,IF(d.contract_id IS NULL,'RESERVATION','SECURITY') category,p.name property_name,COALESCE(u.full_name,'') content,CASE WHEN (d.booking_id IS NOT NULL AND b.status NOT IN ('RESERVED','DEPOSITED')) OR (d.contract_id IS NOT NULL AND c.status IN ('SETTLING','TERMINATED','CANCELLED')) THEN 0 ELSE GREATEST(0,d.required_amount-d.balance_amount) END remaining_deposit_due,COALESCE((SELECT SUM(t.amount) FROM deposit_transactions t WHERE t.deposit_id=d.id AND t.status='CONFIRMED' AND t.transaction_type IN ('COLLECT','TRANSFER_IN')),0) received_amount FROM tenant_deposits d JOIN properties p ON p.id=d.property_id LEFT JOIN contracts c ON c.id=d.contract_id LEFT JOIN rental_bookings b ON b.id=d.booking_id LEFT JOIN users u ON u.id=d.tenant_id";
   case "vouchers" -> "SELECT v.*,v.voucher_code code,v.voucher_date event_date,v.expense_category category,v.payment_method method,v.description content,p.name property_name,u.full_name actor_name FROM payment_vouchers v JOIN properties p ON p.id=v.property_id LEFT JOIN users u ON u.id=v.created_by";
   case "expenses" -> "SELECT e.*,CONCAT(e.source_type,'-',e.source_id) code,e.occurred_on event_date,p.name property_name,COALESCE(v.description,'Chi phí đã xác nhận từ chứng từ nguồn') content,CASE WHEN v.status='PAID' THEN e.amount ELSE 0 END paid_amount,e.amount-CASE WHEN v.status='PAID' THEN e.amount ELSE 0 END payable,COALESCE(v.status,'CONFIRMED') status,v.payee_name,v.payment_method method,v.id voucher_id FROM management_expense_events e JOIN properties p ON p.id=e.property_id LEFT JOIN payment_vouchers v ON (e.source_type='VOUCHER' AND v.id=e.source_id) OR (e.source_type='EXPENSE' AND v.expense_id=e.source_id AND v.status NOT IN ('REJECTED','REVERSED'))";
   case "periods" -> "SELECT a.*,a.period_code code,a.start_date event_date,p.name property_name FROM accounting_periods a JOIN properties p ON p.id=a.property_id";
   case "history" -> "SELECT a.*,CONCAT('LS-',a.id) code,a.created_at event_date,a.entity_type category,a.action status,a.reason content,p.name property_name,u.full_name actor_name FROM financial_audit_logs a JOIN properties p ON p.id=a.property_id LEFT JOIN users u ON u.id=a.actor_id";
   case "reconciliation" -> "SELECT a.*,CONCAT('DS-',a.id) code,a.created_at event_date,IF(a.blocking_count>0,'NEEDS_REVIEW','CHECKED') status,p.name property_name FROM financial_reconciliation_runs a JOIN properties p ON p.id=a.property_id";
   default -> "SELECT e.*,e.occurred_at event_date,e.classification category,'CONFIRMED' status,p.name property_name,CASE WHEN e.method='BANK_TRANSFER' THEN 'MANUAL_CONFIRMATION_NOT_BANK_RECONCILIATION' ELSE 'SOURCE_DOCUMENT' END verification,COALESCE(py.reference_code,dt.reference_code,v.payment_reference,oi.reference_code) reference_code,COALESCE(py.note,dt.reason,v.description,oi.description,'') content,COALESCE(u.full_name,'') actor_name,COALESCE(py.tenant_id,d.tenant_id) tenant_id,COALESCE(i.room_id,c.room_id) room_id FROM (SELECT ce.*, :opening + SUM(cash_in-cash_out) OVER(ORDER BY occurred_at,source_type,source_id ROWS UNBOUNDED PRECEDING) running_balance FROM management_cash_events ce WHERE property_id IN (:ids) AND occurred_at>=:start AND occurred_at<:until"+methodSql+") e JOIN properties p ON p.id=e.property_id LEFT JOIN payments py ON e.source_type='PAYMENT' AND py.id=e.source_id LEFT JOIN invoices i ON i.id=py.invoice_id LEFT JOIN deposit_transactions dt ON e.source_type='DEPOSIT' AND dt.id=e.source_id LEFT JOIN tenant_deposits d ON d.id=dt.deposit_id LEFT JOIN contracts c ON c.id=d.contract_id LEFT JOIN payment_vouchers v ON e.source_type='VOUCHER' AND v.id=e.source_id LEFT JOIN other_income oi ON e.source_type='OTHER_INCOME' AND oi.id=e.source_id LEFT JOIN users u ON u.id=COALESCE(py.received_by,dt.transacted_by,v.paid_by,oi.created_by)";
  };
  args.put("opening",opening);String where=" WHERE q.property_id IN (:ids)"+("deposits".equals(f.tab())?"":" AND q.event_date>=:start AND q.event_date<:until");
  if(blank(f.keyword())!=null){where+=" AND (q.code LIKE :keyword OR q.property_name LIKE :keyword)";args.put("keyword","%"+f.keyword().trim()+"%");}
  if(blank(f.status())!=null){where+=" AND q.status=:status";args.put("status",f.status());}
  if(blank(f.category())!=null&&!Set.of("periods","reconciliation").contains(Objects.toString(f.tab(),""))){where+=" AND q.category=:category";args.put("category",f.category());}
  if(method!=null&&Set.of("vouchers","expenses").contains(Objects.toString(f.tab(),""))){where+=" AND q.method=:method";args.put("method",method);}
  if("receipts".equals(f.tab()))where+=" AND q.cash_in>0";
  long count=db.sql("SELECT COUNT(*) FROM ("+source+") q"+where).params(args).query(Long.class).single();
  args.put("limit",f.size());args.put("offset",f.page()*f.size());var rows=db.sql("SELECT * FROM ("+source+") q"+where+" ORDER BY q.event_date DESC,q.code DESC LIMIT :limit OFFSET :offset").params(args).query().listOfRows();
  if("vouchers".equals(f.tab()))for(var row:rows){long property=((Number)row.get("property_id")).longValue();boolean owner=actor.activeRole()==RoleCode.OWNER,writer=owner||actor.activeRole()==RoleCode.MANAGER&&managerWrite(actor,property)||actor.activeRole()==RoleCode.ACCOUNTANT&&new AccountantPortalRepository(db).permission(actor.id(),"can_record_payment");row.put("canPay",writer);row.put("canApprove",owner&&((Number)row.get("created_by")).longValue()!=actor.id());row.put("canReverse",owner);row.put("canSubmit",((Number)row.get("created_by")).longValue()==actor.id()&&(actor.activeRole()==RoleCode.MANAGER&&managerWrite(actor,property)||actor.activeRole()==RoleCode.ACCOUNTANT&&new AccountantPortalRepository(db).permission(actor.id(),"can_create_voucher")));}
  result.put("rows",rows);result.put("page",f.page());result.put("totalElements",count);result.put("totalPages",(count+f.size()-1)/f.size());
  result.put("permissions",Map.of("createVoucher",actor.activeRole()==RoleCode.MANAGER?managerWrite(actor,f.propertyId()):actor.activeRole()==RoleCode.ACCOUNTANT&&new AccountantPortalRepository(db).permission(actor.id(),"can_create_voucher"),"recordIncome",actor.activeRole()==RoleCode.OWNER||actor.activeRole()==RoleCode.MANAGER&&managerWrite(actor,f.propertyId())||actor.activeRole()==RoleCode.ACCOUNTANT&&new AccountantPortalRepository(db).permission(actor.id(),"can_record_payment")));
  return result;
 }
 private boolean managerWrite(AuthenticatedUser a,Long property){return property!=null&&db.sql("SELECT EXISTS(SELECT 1 FROM manager_property_capabilities WHERE manager_id=:actor AND property_id=:property AND capability='FINANCE_WRITE')").param("actor",a.id()).param("property",property).query(Boolean.class).single();}
 private void writer(AuthenticatedUser a,long property,String permission){finance.scope(a,property);if(a.activeRole()==RoleCode.MANAGER&&!managerWrite(a,property)||a.activeRole()==RoleCode.ACCOUNTANT&&!new AccountantPortalRepository(db).permission(a.id(),permission))throw new AuthException(HttpStatus.FORBIDDEN,"FINANCE_WRITE_DENIED","Không có quyền ghi nhận tại nhà trọ này.");}
 @Transactional public Map<String,Object> createVoucher(AuthenticatedUser a,String key,VoucherCreate r){writer(a,r.propertyId(),"can_create_voucher");if(a.activeRole()==RoleCode.OWNER)throw fail("VOUCHER_SEPARATE_CREATOR_REQUIRED");key(key);finance.open(r.propertyId(),r.voucherDate());var prior=db.sql("SELECT * FROM payment_vouchers WHERE creation_key=:key FOR UPDATE").param("key",key).query().listOfRows().stream().findFirst();if(prior.isPresent()){if(((Number)prior.get().get("property_id")).longValue()!=r.propertyId()||((Number)prior.get().get("created_by")).longValue()!=a.id()||!db.sql("SELECT creation_fingerprint=SHA2(:request,256) FROM payment_vouchers WHERE creation_key=:key FOR UPDATE").param("request",r.toString()).param("key",key).query(Boolean.class).single())throw fail("IDEMPOTENCY_KEY_REUSED");return prior.get();}var repo=new AccountantPortalRepository(db);repo.validateExpenseLink(r);long id=repo.voucher(a.id(),r);db.sql("UPDATE payment_vouchers SET creation_key=:key,creation_fingerprint=SHA2(:request,256) WHERE id=:id").param("key",key).param("request",r.toString()).param("id",id).update();repo.audit(r.propertyId(),a.id(),"PAYMENT_VOUCHER",id,"DRAFT_CREATED",r.description());return db.sql("SELECT * FROM payment_vouchers WHERE id=:id").param("id",id).query().singleRow();}
 @Transactional public void submit(AuthenticatedUser a,long id,long version){var v=db.sql("SELECT * FROM payment_vouchers WHERE id=:id FOR UPDATE").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->fail("VOUCHER_NOT_FOUND"));long property=((Number)v.get("property_id")).longValue();writer(a,property,"can_create_voucher");finance.open(property,((java.sql.Date)v.get("voucher_date")).toLocalDate());var repo=new AccountantPortalRepository(db);if(repo.submitVoucher(a.id(),id,version)!=1)throw fail("VOUCHER_VERSION_OR_STATE_CONFLICT");repo.audit(property,a.id(),"PAYMENT_VOUCHER",id,"SUBMITTED","Gửi chủ nhà duyệt; chưa thực chi.");}
 @Transactional public Map<String,Object> income(AuthenticatedUser a,String key,OtherIncomeCreate r){writer(a,r.propertyId(),"can_record_payment");key(key);if(!Set.of("OTHER_INCOME","SERVICE_OTHER","COMPENSATION","PREPAYMENT","COLLECTION_ON_BEHALF").contains(r.category()))throw fail("INCOME_CATEGORY_INVALID");if(r.incomeDate().isAfter(com.thangit.boardinghouse.service.BusinessTime.today(InvoicePaymentRules.ZONE)))throw fail("FUTURE_CASH_DATE");finance.open(r.propertyId(),r.incomeDate());var repo=new AccountantPortalRepository(db);var prior=db.sql("SELECT * FROM other_income WHERE idempotency_key=:key FOR UPDATE").param("key",key).query().listOfRows().stream().findFirst().orElse(null);if(prior!=null){if(((Number)prior.get("property_id")).longValue()!=r.propertyId()||!db.sql("SELECT request_fingerprint=SHA2(:request,256) FROM other_income WHERE id=:id FOR UPDATE").param("request",r.toString()).param("id",prior.get("id")).query(Boolean.class).single())throw fail("IDEMPOTENCY_KEY_REUSED");return prior;}long id=repo.otherIncome(a.id(),r);repo.incomeKey(id,key,r.toString());repo.audit(r.propertyId(),a.id(),"OTHER_INCOME",id,"CONFIRMED",r.description());return db.sql("SELECT * FROM other_income WHERE id=:id").param("id",id).query().singleRow();}
 public byte[] export(AuthenticatedUser a,Filter f){finance.scope(a,f.propertyId());new AdminInvoiceRepository(db).requireExport(a,f.propertyId());var rows=new ArrayList<List<Object>>();rows.add(List.of("Mã chứng từ","Ngày","Nhà trọ","Phân loại","Trạng thái","Số tiền","Tiền vào","Tiền ra","Lũy kế từ nguồn"));if("deposits".equals(f.tab())){rows.clear();rows.add(List.of("Mã hợp đồng / giữ phòng","Nhà trọ","Loại cọc","Yêu cầu","Đã nhận hợp lệ","Đang giữ","Còn bổ sung","Đối soát"));}for(int page=0;;page++){var data=workspace(a,new Filter(f.propertyId(),f.startDate(),f.endDate(),f.tab(),f.keyword(),f.status(),f.category(),f.method(),page,100,f.organizationId(),f.areaId()));var records=(List<?>)data.get("rows");for(Object record:records){var r=(Map<?,?>)record;if("deposits".equals(f.tab()))rows.add(Arrays.asList(r.get("code"),r.get("property_name"),r.get("category"),r.get("required_amount"),r.get("received_amount"),r.get("balance_amount"),r.get("remaining_deposit_due"),r.get("status")));else rows.add(Arrays.asList(r.get("code"),r.get("event_date"),r.get("property_name"),r.get("category"),r.get("status"),r.get("amount"),r.get("cash_in"),r.get("cash_out"),r.get("running_balance")));}if(page+1>=((Number)data.get("totalPages")).longValue())break;}return InvoiceDocuments.workbook(rows);}
 private static void key(String k){if(k==null||k.isBlank()||k.length()>100)throw fail("IDEMPOTENCY_KEY_REQUIRED");}
 @Transactional public void reverseIncome(AuthenticatedUser a,long id,String reason){
  if(a==null||a.activeRole()!=RoleCode.OWNER)throw new AuthException(HttpStatus.FORBIDDEN,"INCOME_REVERSAL_OWNER_REQUIRED","Chỉ chủ nhà được đảo khoản thu khác.");
  var row=db.sql("SELECT * FROM other_income WHERE id=:id FOR UPDATE").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->fail("INCOME_NOT_FOUND"));
  long property=((Number)row.get("property_id")).longValue();finance.scope(a,property);
  if(reason==null||reason.isBlank()||reason.length()>1000)throw fail("REVERSAL_REASON_REQUIRED");
  finance.open(property,((java.sql.Date)row.get("income_date")).toLocalDate());finance.open(property,com.thangit.boardinghouse.service.BusinessTime.today(InvoicePaymentRules.ZONE));
  if(db.sql("UPDATE other_income SET status='REVERSED' WHERE id=:id AND status='CONFIRMED'").param("id",id).update()!=1)throw fail("INCOME_ALREADY_REVERSED");
  new AccountantPortalRepository(db).audit(property,a.id(),"OTHER_INCOME",id,"REVERSED",reason);
 }
 private static String blank(String s){return s==null||s.isBlank()?null:s.trim();}private static BigDecimal money(Object v){return new BigDecimal(v.toString());}private static AuthException fail(String c){return new AuthException(HttpStatus.CONFLICT,c,"Kiểm tra chứng từ, phạm vi, thời gian và dữ liệu đã thay đổi.");}
}
